-- SAP S/4HANA -> canonical PAYMENT (SAP_B). Generated by tools/build_silver_sql.py.
SELECT 'SAP_B' AS SOURCE_SLOT, 'SAP S/4HANA' AS SOURCE_SYSTEM, a.RBUKRS AS COMPANY_CODE, a.BELNR AS INVOICE_ID, a.LIFNR AS SUPPLIER_ID, a.BUDAT AS INVOICE_DATE, a.NETDT AS DUE_DATE,
  a.AUGDT AS PAYMENT_DATE, -a.WSL AS AMOUNT, a.SKNTO AS DISCOUNT_TAKEN, a.RWCUR AS CURRENCY, a.ZTERM AS PAYMENT_TERMS
FROM {{ source('src_s4_b', 'acdoca') }} a WHERE a.BLART = 'RE' AND a.AUGDT IS NOT NULL
